def lint(method, path):
    segs = [s.lower() for s in path.split('?')[0].split('/') if s]
    warnings = set()
    if any(s in {'get', 'create', 'update', 'delete', 'remove', 'add'} for s in segs):
        warnings.add('verb-in-path')
    if method.upper() == 'GET' and any(s in {'delete', 'remove', 'update', 'create'} for s in segs):
        warnings.add('unsafe-get')
    if segs and not segs[0].endswith('s'):
        warnings.add('singular-collection')
    return sorted(warnings)
